INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2850, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1681399918/noidung/poqhdvxp0ahzh0tl7zwn.txt', null, null, 'Lập Trình ReactJs', 40000, true, '2022-12-06 00:00:00.000000', 200000, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788065/photo/Reactjs_cgenjb.jpg', 'Khóa học Lập Trình ReactJS là một khóa học trực tuyến giúp học viên học cách tạo ra các ứng dụng web động và tương tác cao bằng cách sử dụng ReactJS, một thư viện JavaScript phổ biến. Khóa học này cung cấp kiến thức từ cơ bản đến nâng cao về ReactJS và các công cụ phát triển liên quan, bao gồm các chủ đề như component, state, props, JSX, routing, API, Redux và Redux Saga.', 1);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2851, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'Lập Trình Nodejs', 180000, true, '2022-12-12 00:00:00.000000', 250000, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788065/photo/Nodejs_gody4o.png', 'Node.js là một nền tảng lập trình được xây dựng trên động cơ JavaScript V8 của Google, cho phép các lập trình viên sử dụng JavaScript để lập trình phía máy chủ. Node.js cho phép lập trình viên xây dựng các ứng dụng web và các ứng dụng back-end phức tạp với các tính năng phong phú như đa luồng, xử lý bất đồng bộ, xử lý sự kiện và các công cụ phát triển khác.', 2);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2853, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'Lập Trình Python', 250000, true, '2023-02-03 00:00:00.000000', 800000, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788065/photo/pythonbg_kqizeg.jpg', 'Python là một ngôn ngữ lập trình thông dịch, đa nền tảng và đa mục đích được phát triển bởi Guido van Rossum vào năm 1991. Python đã trở thành một trong những ngôn ngữ lập trình phổ biến nhất trên thế giới với cộng đồng lớn và nhiều tài liệu hướng dẫn. Python được sử dụng để phát triển các ứng dụng máy tính, trang web, ứng dụng di động, trí tuệ nhân tạo, khoa học dữ liệu và nhiều lĩnh vực khác.', 1);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2855, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'HTML-CSS Cơ Bản', 0, true, '2023-02-03 00:00:00.000000', 0, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788063/photo/htmlcss_kugcnd.png', 'HTML (Hypertext Markup Language) và CSS (Cascading Style Sheets) là những ngôn ngữ lập trình cơ bản được sử dụng để thiết kế các trang web. HTML được sử dụng để định dạng nội dung trên trang web, trong khi CSS được sử dụng để tạo kiểu và trang trí cho trang web. Khóa học HTML-CSS Cơ bản sẽ giúp bạn học cách sử dụng HTML và CSS để tạo ra các trang web đẹp và chuyên nghiệp.', 2);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2856, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'Lập Trình Java Cơ Bản', 200000, true, '2023-02-03 00:00:00.000000', 400000, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788063/photo/java_o4vn6q.jpg', 'Java là một ngôn ngữ lập trình phổ biến được sử dụng rộng rãi trong phát triển ứng dụng máy tính và web. Java là một ngôn ngữ lập trình đa nền tảng, có thể chạy trên nhiều hệ điều hành khác nhau và có thể được sử dụng để phát triển các ứng dụng cho desktop, web và di động.', 1);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2858, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'Lập Trình javascript Cơ Bản', 0, true, '2023-02-03 00:00:00.000000', 0, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788064/photo/javasciptcoban_yfqvgv.jpg', 'JavaScript là một ngôn ngữ lập trình phổ biến, được sử dụng phổ biến cho các ứng dụng web và mobile. Nó là một ngôn ngữ lập trình được thực thi trên máy khách (client-side), có nghĩa là mã được thực thi trên trình duyệt của người dùng thay vì được thực thi trên máy chủ.', 2);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2860, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'Thiết Kế Giao Diện Bằng Bootrap', 0, true, '2023-03-05 00:00:00.000000', 0, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788061/photo/bootstrap_ubftzy.png', 'Bootstrap là một bộ công cụ HTML, CSS và JavaScript mã nguồn mở được thiết kế để giúp tạo giao diện web đẹp và dễ dàng cho các lập trình viên. Bootstrap được tạo ra bởi Twitter và đã được phát hành dưới giấy phép MIT. Khóa học Bootstrap sẽ giúp bạn học cách sử dụng bộ công cụ này để xây dựng các giao diện web độc đáo và chuyên nghiệp. Khóa học sẽ giới thiệu cho bạn các khái niệm cơ bản về Bootstrap, bao gồm cách sử dụng lưới (grid system) để xây dựng trang web đáp ứng (responsive web design), cách sử dụng các thành phần (component) như nút, biểu mẫu, bảng, thẻ, hộp thoại, v.v. để tạo giao diện đẹp mắt và dễ sử dụng.', 1);
INSERT INTO khoahoc.course (tps_id, learn, str_tps_discount, str_tps_price, tps_name, tps_price, tps_status, tps_date, tps_discount, tps_image, tps_information, tps_categoryid) VALUES (2862, 'https://res.cloudinary.com/djfbh9dqg/raw/upload/v1679386946/2850_xchao3.txt', null, null, 'Xây dựng website hoàn chỉnh với Laravel PHP Framework', 0, true, '2023-03-05 00:00:00.000000', 0, 'https://res.cloudinary.com/djfbh9dqg/image/upload/v1678788064/photo/laravel_btuicp.jpg', 'Laravel là một framework mã nguồn mở được sử dụng rộng rãi để xây dựng các ứng dụng web dựa trên ngôn ngữ lập trình PHP. Laravel cung cấp cho các lập trình viên một cách tiếp cận dễ dàng và hiệu quả để xây dựng các ứng dụng web với các tính năng phong phú như xử lý tệp, chứng thực, phân quyền, định tuyến, xử lý email và cả tạo và quản lý cơ sở dữ liệu.', 2);
